import{_ as t,a as o,o as a,a4 as i}from"./chunks/framework.-FZumj2l.js";const b=JSON.parse('{"title":"Bookings","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/sales/bookings/index.md","filePath":"api/graphql-api/admin/sales/bookings/index.md","lastUpdated":1783420618000}'),n={name:"api/graphql-api/admin/sales/bookings/index.md"};function r(d,e,s,h,l,c){return a(),o("div",null,e[0]||(e[0]=[i('<h1 id="bookings" tabindex="-1">Bookings <a class="header-anchor" href="#bookings" aria-label="Permalink to &quot;Bookings&quot;">​</a></h1><p>The Bookings menu is a read-only list of booking lines produced by orders that contain a booking product. It mirrors the admin <strong>Sales → Bookings</strong> screen. This menu is <strong>read-only</strong> — list and detail only; booking rows are created automatically when an order is placed and cannot be created or edited through the API.</p><h2 id="when-a-row-appears-here" tabindex="-1">When a row appears here <a class="header-anchor" href="#when-a-row-appears-here" aria-label="Permalink to &quot;When a row appears here&quot;">​</a></h2><p>A row appears whenever an order is placed that contains a booking product — each booked line shows here. A booking row carries the booked quantity, the from/to time window, and a summary of the order and order item it belongs to.</p><h2 id="booking-sub-types" tabindex="-1">Booking sub-types <a class="header-anchor" href="#booking-sub-types" aria-label="Permalink to &quot;Booking sub-types&quot;">​</a></h2><p>The <code>bookingType</code> field tells you what kind of booking the line is — it comes from the booked product&#39;s configuration:</p><table tabindex="0"><thead><tr><th><code>bookingType</code></th><th>Meaning</th></tr></thead><tbody><tr><td><code>default</code></td><td>A simple bookable product with a fixed availability window.</td></tr><tr><td><code>appointment</code></td><td>A time-slot appointment (e.g. a service booking).</td></tr><tr><td><code>event</code></td><td>A ticketed event. The booking also carries a <code>bookingProductEventTicketId</code> identifying which ticket type was booked.</td></tr><tr><td><code>rental</code></td><td>A rental booked for a date/time range (hourly or daily).</td></tr><tr><td><code>table</code></td><td>A table reservation (e.g. restaurant), for a party at a time.</td></tr></tbody></table><h2 id="the-booking-window" tabindex="-1">The booking window <a class="header-anchor" href="#the-booking-window" aria-label="Permalink to &quot;The booking window&quot;">​</a></h2><p>The booked time window is returned twice: <code>from</code> / <code>to</code> as raw <strong>unix timestamps</strong> (integers, for programmatic use) and <code>fromFormatted</code> / <code>toFormatted</code> as readable strings. Some sub-types are not strictly time-windowed, so all four can be <code>null</code> for those rows.</p><h2 id="what-the-booking-detail-embeds" tabindex="-1">What the booking detail embeds <a class="header-anchor" href="#what-the-booking-detail-embeds" aria-label="Permalink to &quot;What the booking detail embeds&quot;">​</a></h2><p>In the admin, viewing a booking jumps to the underlying order view. The booking detail mirrors that by embedding the order&#39;s <strong>billing and shipping address</strong>, its <strong>payment &amp; shipping info</strong> (payment method/title, shipping method/title), and its <strong>invoices, shipments and refunds</strong> — matching what the admin Booking view shows when it opens the order. Addresses can be <code>null</code> when the order has none, and the invoices/shipments/refunds arrays are empty when there are none. These are returned as whole JSON objects/arrays — query them bare (no sub-field selection).</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/sales/bookings/list.html">List bookings</a></td><td><code>adminBookings</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/sales/bookings/detail.html">Get a single booking</a></td><td><code>adminBooking(id:)</code> query</td></tr></tbody></table><p>All Bookings operations require the <code>sales.bookings.view</code> permission and an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',14)]))}const g=t(n,[["render",r]]);export{b as __pageData,g as default};
